INSERT INTO products (id, category_id, name, summary, description, price_cents, compare_at_cents, stock, rating, reviews_count, featured, image, origin, roast, process, altitude, notes, profile, sizes, colors, details, art, created_at) VALUES
  ('yirgacheffe-sunrise', 'beans', 'Yirgacheffe Sunrise', 'Floral and bright, with lemon curd sweetness.', 'A washed lot from smallholder farms near Yirgacheffe. Roasted light to keep the florals intact, it brews clean and tea-like. Best as a pour-over or in an AeroPress.', 1800, NULL, 64, 4.9, 212, 1, '/products/yirgacheffe-sunrise.webp', 'Ethiopia', 'Light', 'Washed', '1,900 m', '["Jasmine","Lemon curd","Peach"]', '{"acidity":5,"body":2,"sweetness":4}', '[{"label":"250 g","price_cents":1800},{"label":"1 kg","price_cents":6200}]', NULL, NULL, '{"type":"bag","color":"#8C2F39","label":"Yirgacheffe","sub":"Ethiopia"}', '2026-09-02'),
  ('huila-honey', 'beans', 'Huila Honey', 'Sticky panela sweetness and red apple.', 'Honey-processed lot from the Huila highlands. Round, sweet and easy to like, it works in every brewer and makes a lovely milk coffee.', 1600, NULL, 90, 4.8, 168, 1, '/products/huila-honey.webp', 'Colombia', 'Medium', 'Honey', '1,750 m', '["Panela","Red apple","Milk chocolate"]', '{"acidity":3,"body":3,"sweetness":5}', '[{"label":"250 g","price_cents":1600},{"label":"1 kg","price_cents":5500}]', NULL, NULL, '{"type":"bag","color":"#B9975B","label":"Huila Honey","sub":"Colombia","ink":"#141714"}', '2026-09-09'),
  ('kiambu-aa', 'beans', 'Kiambu AA', 'Juicy blackcurrant with a grapefruit snap.', 'Large-screen AA beans from cooperatives north of Nairobi. Loud, juicy and structured. Brews beautifully as a filter coffee and holds up over ice.', 1900, NULL, 38, 4.9, 141, 1, '/products/kiambu-aa.webp', 'Kenya', 'Light', 'Washed', '1,800 m', '["Blackcurrant","Grapefruit","Brown sugar"]', '{"acidity":5,"body":3,"sweetness":3}', '[{"label":"250 g","price_cents":1900},{"label":"1 kg","price_cents":6600}]', NULL, NULL, '{"type":"bag","color":"#3B2A4A","label":"Kiambu AA","sub":"Kenya"}', '2026-09-16'),
  ('cerrado-sweet', 'beans', 'Cerrado Sweet', 'Hazelnut, cocoa and a long caramel finish.', 'A natural-process Brazilian roasted a little darker for a thick, chocolatey cup. A dependable everyday coffee, and a favourite for moka pots.', 1400, NULL, 120, 4.7, 305, 0, '/products/cerrado-sweet.webp', 'Brazil', 'Medium-dark', 'Natural', '1,150 m', '["Hazelnut","Cocoa","Caramel"]', '{"acidity":2,"body":4,"sweetness":4}', '[{"label":"250 g","price_cents":1400},{"label":"1 kg","price_cents":4800}]', NULL, NULL, '{"type":"bag","color":"#2F5D46","label":"Cerrado Sweet","sub":"Brazil"}', '2026-08-21'),
  ('antigua-volcan', 'beans', 'Antigua Volcán', 'Dark chocolate, orange zest and toasted almond.', 'Grown in volcanic soil around Antigua. Balanced, with a gentle citrus lift over a chocolatey base. A great all-rounder for drip machines.', 1600, NULL, 77, 4.8, 122, 0, '/products/antigua-volcan.webp', 'Guatemala', 'Medium', 'Washed', '1,600 m', '["Dark chocolate","Orange zest","Almond"]', '{"acidity":3,"body":4,"sweetness":4}', '[{"label":"250 g","price_cents":1600},{"label":"1 kg","price_cents":5500}]', NULL, NULL, '{"type":"bag","color":"#1F5560","label":"Antigua Volcán","sub":"Guatemala"}', '2026-08-30'),
  ('house-blend-no1', 'beans', 'House Blend No. 1', 'Toffee and roasted nuts. Our all-day coffee.', 'Brazil and Colombia, blended for sweetness and body. It tastes the same every month, works as espresso or filter, and takes milk well.', 1500, NULL, 150, 4.8, 489, 1, '/products/house-blend-no1.webp', 'Blend', 'Medium-dark', 'Mixed', 'Various', '["Toffee","Roasted nuts","Dark chocolate"]', '{"acidity":2,"body":5,"sweetness":4}', '[{"label":"250 g","price_cents":1500},{"label":"1 kg","price_cents":5200}]', NULL, NULL, '{"type":"bag","color":"#1D2A4A","label":"House Blend","sub":"No. 1"}', '2026-07-14'),
  ('midnight-espresso', 'beans', 'Midnight Espresso', 'Molasses, cocoa nib and a little smoke.', 'A dark, syrupy espresso blend built to cut through milk. Low acidity, heavy crema and a finish that lingers.', 1500, NULL, 18, 4.6, 97, 0, '/products/midnight-espresso.webp', 'Blend', 'Dark', 'Mixed', 'Various', '["Molasses","Cocoa nib","Smoke"]', '{"acidity":1,"body":5,"sweetness":3}', '[{"label":"250 g","price_cents":1500},{"label":"1 kg","price_cents":5200}]', NULL, NULL, '{"type":"bag","color":"#1A1B1E","label":"Midnight","sub":"Espresso"}', '2026-07-28'),
  ('swiss-water-decaf', 'beans', 'Swiss Water Decaf', 'Caramel and cherry, minus the caffeine.', 'Colombian coffee decaffeinated with water only. It keeps its sweetness and body, so the evening cup still tastes like coffee.', 1700, NULL, 52, 4.5, 76, 0, '/products/swiss-water-decaf.webp', 'Decaf', 'Medium', 'Swiss Water', '1,700 m', '["Caramel","Cherry","Cocoa"]', '{"acidity":3,"body":3,"sweetness":4}', '[{"label":"250 g","price_cents":1700},{"label":"1 kg","price_cents":5800}]', NULL, NULL, '{"type":"bag","color":"#C98E94","label":"Swiss Water","sub":"Decaf","ink":"#141714"}', '2026-08-05'),
  ('ceramic-cone-dripper', 'gear', 'Ceramic Cone Dripper', 'A spiral-ribbed pour-over cone for clean, sweet cups.', 'Heavy glazed ceramic holds heat while you brew. The spiral ribs and single large hole give you control over flow. Fits size 02 paper filters and most mugs.', 2800, NULL, 45, 4.8, 134, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["Glazed ceramic","Fits size 02 filters","Makes 1–2 cups","Dishwasher safe"]', '{"type":"dripper","color":"#B9975B"}', '2026-06-20'),
  ('gooseneck-kettle', 'gear', 'Gooseneck Kettle 0.8 L', 'Precise pour, stainless steel, induction ready.', 'The long curved spout gives a thin, steady stream for even extraction. Stainless steel with a heat-proof handle, a lid thermometer port and a flat base that works on every hob.', 6400, 7900, 22, 4.7, 88, 0, '/products/gooseneck-kettle.webp', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["0.8 L capacity","304 stainless steel","Works on induction","Thermometer port"]', '{"type":"kettle","color":"#1D2A4A"}', '2026-06-24'),
  ('hand-burr-grinder', 'gear', 'Hand Burr Grinder', 'Steel burrs and 40 click settings. Quiet and portable.', 'Conical steel burrs grind evenly from espresso to French press. The aluminium body fits in a bag, and the 30 g chamber is enough for two cups.', 8900, NULL, 31, 4.9, 203, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["Conical steel burrs","40 click settings","30 g capacity","Aluminium body"]', '{"type":"grinder","color":"#8C2F39"}', '2026-07-01'),
  ('precision-scale', 'gear', 'Precision Coffee Scale', '0.1 g accuracy with a built-in brew timer.', 'Weigh beans and water to the tenth of a gram. Auto-tare, a flow-rate display and a silicone mat that keeps spills off the sensor.', 4200, NULL, 0, 4.6, 61, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["0.1 g resolution","Built-in timer","USB-C charging","Silicone mat"]', '{"type":"scale","color":"#2F5D46"}', '2026-07-06'),
  ('stoneware-mug', 'cups', 'Stoneware Mug 300 ml', 'Hand-glazed stoneware that holds heat.', 'Thick walls, a wide comfortable handle and a speckled glaze that is different on every mug. Microwave and dishwasher safe.', 2200, NULL, 84, 4.8, 157, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[{"label":"Oat","value":"#D9D0BD"},{"label":"Garnet","value":"#8C2F39"},{"label":"Pine","value":"#2F5D46"}]', '["300 ml","Stoneware","Microwave safe","Dishwasher safe"]', '{"type":"mug","color":"#D9D0BD"}', '2026-06-12'),
  ('travel-tumbler', 'cups', 'Insulated Travel Tumbler', 'Keeps coffee hot for 6 hours and cold for 12.', 'Double-wall steel with a leak-resistant lid and a slim base that fits a car cup holder. No flavour transfer, so it tastes like coffee every time.', 3400, NULL, 59, 4.7, 119, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[{"label":"Brass","value":"#B9975B"},{"label":"Teal","value":"#1F5560"},{"label":"Plum","value":"#3B2A4A"}]', '["350 ml","Double-wall steel","Hot 6 h / cold 12 h","Leak-resistant lid"]', '{"type":"tumbler","color":"#B9975B"}', '2026-06-30'),
  ('tasting-flight-box', 'gifts', 'Tasting Flight Gift Box', 'Three 100 g bags from three origins, ready to give.', 'Our best way to meet the range: Ethiopia, Colombia and Brazil in 100 g bags, with a tasting card for each. Packed in a reusable gift box with a handwritten note if you want one.', 3900, NULL, 40, 5, 93, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["3 × 100 g bags","Tasting cards included","Gift note option","Plastic-free packaging"]', '{"type":"giftbox","color":"#8C2F39","accent":"#B9975B"}', '2026-10-01'),
  ('pour-over-starter-kit', 'gifts', 'Pour-Over Starter Kit', 'Dripper, kettle, scale and a bag of House Blend.', 'Everything needed for a first great cup at home: the ceramic dripper, gooseneck kettle, coffee scale, 100 filters and 250 g of House Blend No. 1, in one box.', 11900, 13500, 14, 4.9, 58, 1, '/products/pour-over-starter-kit.webp', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["Ceramic dripper","Gooseneck kettle 0.8 L","Coffee scale","250 g House Blend No. 1"]', '{"type":"giftbox","color":"#1D2A4A","accent":"#EEF0E8"}', '2026-10-08'),
  ('sumatra-mandheling', 'beans', 'Sumatra Mandheling', 'Earthy and syrupy, with cedar and dark cocoa.', 'A wet-hulled lot from the highlands of North Sumatra, roasted dark for a heavy body and a long, smoky finish. It stands up to milk and makes a bold French press.', 1900, NULL, 58, 4.7, 134, 0, '/products/sumatra-mandheling.webp', 'Indonesia', 'Dark', 'Wet-hulled', '1,400 m', '["Dark cocoa","Cedar","Brown sugar"]', '{"acidity":1,"body":5,"sweetness":3}', '[{"label":"250 g","price_cents":1900},{"label":"1 kg","price_cents":6600}]', NULL, NULL, '{"type":"bag","color":"#1D2A4A","label":"Sumatra","sub":"Indonesia"}', '2026-10-15'),
  ('copper-french-press', 'gear', 'Copper French Press 600 ml', 'Borosilicate glass in a polished copper frame.', 'A full-bodied brew in four minutes. Heat-resistant borosilicate glass, a fine double mesh filter and a copper-finish frame with a matte black handle.', 5800, 6900, 26, 4.8, 71, 0, '/products/copper-french-press.webp', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["600 ml, about 4 cups","Borosilicate glass","Double mesh filter","Dishwasher-safe parts"]', '{"type":"kettle","color":"#B9975B"}', '2026-10-18'),
  ('emerald-moka-pot', 'gear', 'Emerald Moka Pot 6-cup', 'Stovetop espresso-style coffee in enamelled aluminium.', 'A classic eight-sided moka pot in deep green enamel with a brass-tone ring and a heat-safe handle. It brews a rich, concentrated cup on any gas or electric hob.', 4200, NULL, 33, 4.6, 49, 0, '/products/emerald-moka-pot.webp', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["6 cups, about 300 ml","Enamelled aluminium","Heat-safe handle","Not for induction"]', '{"type":"kettle","color":"#1F5A3A"}', '2026-10-20');
